import { readFileSync, writeFileSync } from 'node:fs';
import { setTimeout as delay } from 'node:timers/promises';
import { ownedProcesses, processes, signalOwned, sameProcess } from './spn135-local-processes.ts';
import type { ProcessRow } from './spn135-local-processes.ts';
async function main() {
const [source, destination] = process.argv.slice(2);
const snapshot = JSON.parse(readFileSync(source, 'utf8'));
const known = new Map<number, ProcessRow>(snapshot.known.map((row: ProcessRow) => [row.pid, row]));
// Do not claim a reused root PID or newly launched sibling belongs to this task.
const before = ownedProcesses(processes(), -1, known);
signalOwned(known, 'SIGTERM', process.pid);
if (before.length) await delay(750);
const afterTerm = ownedProcesses(processes(), -1, known);
signalOwned(known, 'SIGKILL', process.pid);
if (afterTerm.length) await delay(250);
const remaining = processes().filter(row => known.has(row.pid) && sameProcess(known.get(row.pid)!, row));
writeFileSync(destination, JSON.stringify({ snapshot: source, before, afterTerm, remaining, scope: snapshot.scope }, null, 2) + '\n');
console.log(JSON.stringify({ before: before.length, afterTerm: afterTerm.length, remaining: remaining.length }));
if (remaining.length) process.exitCode = 1;
}
void main().catch(error => { console.error(error); process.exitCode = 1; });

